// Token Launch Radar — dashboard behaviour.
//
// The data arrives as window.RADAR (see data.js, generated by the entry's
// main.ts from the same radar object the scorer grades). This file only
// presents it: filters, four sort orders plus clickable headings, the
// multiples evidence table, and a per-protocol detail view.

'use strict';

const R = window.RADAR;
const rows = R.rows;

const $ = (id) => document.getElementById(id);
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// $2.75B, $499.1M, $950K — the board's house style for money.
function fmtUsd(v) {
  if (v >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v / 1e6).toFixed(1) + 'M';
  if (v >= 1e3) return '$' + Math.round(v / 1e3) + 'K';
  return '$' + Math.round(v);
}

const fmtPct = (v) => (v === null ? '—' : (v > 0 ? '+' : '') + v.toFixed(1) + '%');
const fmtMult = (v) => '×' + v.toFixed(3);
const fmtFactor = (v) => '×' + v.toFixed(3);

// "Base, Ethereum +9" — the first two chains, then a count of the rest.
function fmtChains(chains) {
  if (chains.length <= 2) return chains.join(', ');
  return chains.slice(0, 2).join(', ') + ' +' + (chains.length - 2);
}

// ------------------------------------------------------------- masthead

$('meta-line').textContent =
  'Snapshot: ' + R.source + ', fetched ' + R.as_of + ' · ' + rows.length +
  ' pre-token protocols ranked · all ' + R.watchlist_size + ' watchlist protocols covered';

// ------------------------------------------------- multiples evidence

function renderMultiples() {
  const body = $('multiples-body');
  let html = '';
  for (const m of R.multiples) {
    html += '<tr><td>' + esc(m.category) + '</td><td class="num">' + m.peers + '</td>' +
      '<td class="num">' + fmtMult(m.median) + '</td><td class="num applied">' + fmtMult(m.applied) + '</td></tr>';
  }
  const g = R.global_multiple;
  html += '<tr><td>All categories</td><td class="num">' + g.peers + '</td>' +
    '<td class="num">' + fmtMult(g.median) + '</td><td class="num applied">' + fmtMult(g.applied) + '</td></tr>';
  body.innerHTML = html;
}

// ------------------------------------------------------------- filters

const state = { q: '', cat: '', chain: '', watch: false, key: 'value', flipped: false };

function fillSelect(el, values) {
  for (const v of values) {
    const opt = document.createElement('option');
    opt.value = v;
    opt.textContent = v;
    el.appendChild(opt);
  }
}

fillSelect($('cat'), [...new Set(rows.map((r) => r.category).filter(Boolean))].sort());
fillSelect($('chain'), [...new Set(rows.flatMap((r) => r.chains))].sort());

const sorters = {
  value: (a, b) => b.implied_value_usd - a.implied_value_usd,
  rank: (a, b) => a.rank - b.rank,
  tvl: (a, b) => b.tvl_usd - a.tvl_usd,
  change: (a, b) => (b.change_7d ?? -Infinity) - (a.change_7d ?? -Infinity),
  years: (a, b) => (b.years_tokenless ?? -1) - (a.years_tokenless ?? -1),
};

function visibleRows() {
  const q = state.q.toLowerCase();
  const list = rows.filter((r) =>
    (!q || r.name.toLowerCase().includes(q) || (r.category || '').toLowerCase().includes(q)) &&
    (!state.cat || r.category === state.cat) &&
    (!state.chain || r.chains.includes(state.chain)) &&
    (!state.watch || r.on_watchlist));
  const sorter = sorters[state.key] || sorters.value;
  // Each comparator already points the board's natural way (rank ascending,
  // everything else biggest first); a repeat heading click flips it.
  list.sort((a, b) => (state.flipped ? -sorter(a, b) : sorter(a, b)));
  return list;
}

function renderBoard() {
  const list = visibleRows();
  let html = '';
  for (const r of list) {
    html += '<tr data-slug="' + esc(r.slug) + '">' +
      '<td class="rank">' + r.rank + '</td>' +
      '<td class="name">' + esc(r.name) + (r.on_watchlist ? '<span class="badge">Watchlist</span>' : '') + '</td>' +
      '<td class="cat">' + esc(r.category ?? '—') + '</td>' +
      '<td class="chains">' + esc(fmtChains(r.chains)) + '</td>' +
      '<td>' + fmtUsd(r.tvl_usd) + '</td>' +
      '<td class="' + (r.change_7d === null ? '' : r.change_7d >= 0 ? 'up' : 'down') + '">' + fmtPct(r.change_7d) + '</td>' +
      '<td>' + (r.years_tokenless === null ? '—' : r.years_tokenless) + '</td>' +
      '<td>' + fmtMult(r.multiple) + '</td>' +
      '<td class="value">' + fmtUsd(r.implied_value_usd) + '</td></tr>';
  }
  $('board-body').innerHTML = html || '<tr><td colspan="9">No protocol matches those filters.</td></tr>';
  $('count').textContent = 'Showing ' + list.length + ' of ' + rows.length + ' protocols';
  for (const tr of $('board-body').querySelectorAll('tr[data-slug]')) {
    tr.addEventListener('click', () => openDetail(tr.dataset.slug));
  }
  markActiveHeading();
}

function markActiveHeading() {
  for (const th of document.querySelectorAll('.board th[data-sort]')) {
    const on = th.dataset.sort === state.key;
    th.classList.toggle('active', on);
    th.classList.toggle('asc', on && state.flipped);
  }
}

// -------------------------------------------------------------- detail

function formulaLines(r) {
  const g = R.global_multiple;
  let basis;
  if (r.multiple_category === 'all categories') {
    basis = '(the all-category median from ' + g.peers + ' traded peers — ' +
      (r.category ?? 'this category') + ' has fewer than three of its own)';
  } else {
    basis = '(' + r.multiple_category + ' median ' + fmtMult(r.multiple_median) + ' from ' +
      r.multiple_peers + ' traded peers, blended toward the all-category median ' +
      fmtMult(g.median) + ' by peer count)';
  }
  const lines = [
    'TVL ' + fmtUsd(r.tvl_usd) + ' × applied multiple ' + fmtMult(r.multiple),
    basis,
    '× momentum ' + fmtFactor(r.momentum_factor) + ' (7-day TVL ' + fmtPct(r.change_7d) + ')',
    '× longevity ' + fmtFactor(r.longevity_factor) +
      (r.years_tokenless === null ? ' (listing date not recorded)' : ' (' + r.years_tokenless + (r.years_tokenless === 1 ? ' year' : ' years') + ', no token)'),
    '× breadth ' + fmtFactor(r.breadth_factor) + ' (' + r.chains.length + (r.chains.length === 1 ? ' chain' : ' chains') + ')',
  ];
  return lines.map((l) => '<p>' + esc(l) + '</p>').join('');
}

function openDetail(slug) {
  const r = rows.find((x) => x.slug === slug);
  if (!r) return;
  $('detail-body').innerHTML =
    '<h2>' + esc(r.name) + '</h2>' +
    '<p class="sub">Rank #' + r.rank + ' · ' + esc(r.category ?? 'Uncategorised') + ' · ' + esc(r.chains.join(', ')) +
    (r.on_watchlist ? '<span class="badge">Watchlist</span>' : '') + '</p>' +
    '<div class="big">' + fmtUsd(r.implied_value_usd) + '</div>' +
    '<div class="big-label">Implied launch value</div>' +
    '<div class="formula">' + formulaLines(r) + '</div>' +
    '<div class="stats">' +
    '<div><div class="k">TVL</div><div class="v">' + fmtUsd(r.tvl_usd) + '</div></div>' +
    '<div><div class="k">7-day change</div><div class="v">' + fmtPct(r.change_7d) + '</div></div>' +
    '<div><div class="k">Tracked since</div><div class="v">' + esc(r.listed_at ?? 'not recorded') + '</div></div>' +
    '<div><div class="k">Token</div><div class="v">none recorded</div></div>' +
    '</div>' +
    '<h3>How to farm it</h3>' +
    '<ol class="farm">' + r.farm_steps.map((s) => '<li>' + esc(s) + '</li>').join('') + '</ol>';
  $('detail').hidden = false;
}

$('detail-close').addEventListener('click', () => { $('detail').hidden = true; });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') $('detail').hidden = true; });

// -------------------------------------------------------------- events

$('q').addEventListener('input', (e) => { state.q = e.target.value; renderBoard(); });
$('cat').addEventListener('change', (e) => { state.cat = e.target.value; renderBoard(); });
$('chain').addEventListener('change', (e) => { state.chain = e.target.value; renderBoard(); });
$('watch').addEventListener('change', (e) => { state.watch = e.target.checked; renderBoard(); });
$('sort').addEventListener('change', (e) => { state.key = e.target.value; state.flipped = false; renderBoard(); });

for (const th of document.querySelectorAll('.board th[data-sort]')) {
  th.addEventListener('click', () => {
    const key = th.dataset.sort;
    if (state.key === key) {
      state.flipped = !state.flipped;
    } else {
      state.key = key;
      state.flipped = false;
    }
    if (['value', 'tvl', 'change', 'years'].includes(state.key)) $('sort').value = state.key;
    renderBoard();
  });
}

renderMultiples();
renderBoard();
